'use strict';

const defaultCookies = [
    'Session_id',
    'Secure_session_id',
    'sessionid2',
    'Eda_id',
    'edaid2',
    'yandex_login',
    'sessguard',
];
/**
 * Обфусцирует паспортные куки авторизации в http заголовке.
 *
 * Пример подключения:
 *   require('@yandex-int/yandex-logger/middleware/secure-passport-cookie')({
 *       field: 'req.headers.cookie'
 *   });
 *
 * Пример лога:
 *   logger.info({ req: { headers: { cookie: 'user_id=123;Session_id=aa.bb.cc.dddd;foo=bar' }}}
 *
 *   output:
 *      {"req":{"headers":{"cookie":"user_id=123;Session_id=aa.bb.cc.XXXX;foo=bar"}}}
 *
 * @param {Object} [config]
 * @returns {Function}
 * @see https://wiki.yandex-team.ru/logfeller/security/
 */
module.exports = config => {
    config = config || {};

    return require('./secure-cookie')({
        field: config.field,
        cookies: config.cookies || defaultCookies,
        secureValue,
    });
};

/**
 * @param {String} value
 * @returns {String}
 */
function secureValue(value) {
    let parts = value.split('.');
    let index = parts.length - 1;
    parts[index] = 'X'.repeat(parts[index].length);
    return parts.join('.');
}
